+      const selections = hasSelections ? (symbols.anonymousSelectKey in selected ? selected[symbols.anonymousSelectKey] : selected) : value;
+      results.push(handler(selections, value) as output);
+    }
+    if (results.length) return results;
+    if (fallback) return [fallback(value)];
