+import { NonExhaustiveError } from './errors';
+import { matchPattern } from './internals/helpers';
+import * as symbols from './internals/symbols';
+import { Pattern } from './types/Pattern';
+import { MatchEach } from './types/MatchEach';
+
+type Clause<input> = { patterns?: Pattern<input>[]; predicate?: (value: input) => unknown; handler: (selection: unknown, value: input) => unknown };
+type Operation<input> = { type: 'clause'; clause: Clause<input> } | { type: 'tap'; callback: (result: unknown) => unknown };
+
+/**
+ * Creates a non-short-circuiting pattern matching expression. Every matching
+ * clause contributes its handler result, in declaration order.
+ */
+export function matchEach<const input, output = symbols.unset>(value: input): MatchEach<input, output>;
+export function matchEach<input, output = symbols.unset>(): MatchEach<input, output>;
+export function matchEach<input, output = symbols.unset>(value?: input): MatchEach<input, output> {
+  return new MatchEachExpression<input, output>(value, []) as any;
+}
+
+class MatchEachExpression<input, output> {
+  constructor(private value: input | undefined, private operations: readonly Operation<input>[]) {}
+
+  with(...args: any[]): MatchEachExpression<input, output> {
+    const handler = args[args.length - 1];
+    const patterns: Pattern<input>[] = [args[0]];
+    let predicate: ((value: input) => unknown) | undefined;
+    if (args.length === 3 && typeof args[1] === 'function') predicate = args[1];
+    else if (args.length > 2) patterns.push(...args.slice(1, -1));
+    return this.add({ type: 'clause', clause: { patterns, predicate, handler } });
+  }
+
+  when(predicate: (value: input) => unknown, handler: (value: input) => output): MatchEachExpression<input, output> {
+    return this.add({ type: 'clause', clause: { predicate, handler } });
+  }
+
+  tap(callback: (result: output) => unknown): MatchEachExpression<input, output> {
+    return this.add({ type: 'tap', callback });
+  }
+
+  otherwise(handler: (value: input) => output): output[] {
+    return this.evaluate(this.value as input, handler, false)!;
+  }
+
+  exhaustive(handler?: (value: input) => output): output[] {
+    return this.evaluate(this.value as input, handler, true)!;
+  }
+
+  run(): output[] { return this.evaluate(this.value as input, undefined, true)!; }
+  returnType() { return this; }
+  narrow() { return this; }
+  toFunction(): (input: input) => output[] { return (value) => this.evaluate(value, undefined, true)!; }
+  toExhaustiveFunction(): (input: input) => output[] { return this.toFunction(); }
+  toPartialFunction(): (input: input) => output[] | undefined { return (value) => this.evaluate(value, undefined, false); }
+
+  private add(operation: Operation<input>): MatchEachExpression<input, output> {
+    return new MatchEachExpression(this.value, [...this.operations, operation]);
+  }
+
+  private evaluate(value: input, fallback: ((value: input) => output) | undefined, throwOnEmpty: boolean): output[] | undefined {
+    const results: output[] = [];
+    for (const operation of this.operations) {
+      if (operation.type === 'tap') {
+        results.forEach(operation.callback);
+        continue;
+      }
+      const { patterns, predicate, handler } = operation.clause;
+      let hasSelections = false;
+      const selected: Record<string, unknown> = {};
+      const select = (key: string, selectedValue: unknown) => { hasSelections = true; selected[key] = selectedValue; };
+      const matched = (patterns ? patterns.some((pattern) => matchPattern(pattern, value, select)) : true) && (!predicate || Boolean(predicate(value)));
+      if (!matched) continue;
+      const selections = hasSelections ? (symbols.anonymousSelectKey in selected ? selected[symbols.anonymousSelectKey] : selected) : value;
+      results.push(handler(selections, value) as output);
+    }
+    if (results.length) return results;
+    if (fallback) return [fallback(value)];
+    if (throwOnEmpty) throw new NonExhaustiveError(value);
+    return undefined;
+  }
